tool_input.command:
cd ~/.claude/.tycon-pipeline && node -e '
const fs=require("fs"),p=require("path");
const roots=["timing-history"]; try{for(const m of fs.readdirSync("corridas-buzon")){if(fs.statSync(p.join("corridas-buzon",m)).isDirectory())roots.push(p.join("corridas-buzon",m));}}catch{}
let tot=0,rel=[];
for(const r of roots){for(const f of fs.readdirSync(r)){if(!f.endsWith(".json"))continue;try{const d=JSON.parse(fs.readFileSync(p.join(r,f),"utf8"));if(!d.marker)continue;tot++;const rp=d.marker.repoPath;if(rp&&!p.isAbsolute(rp))rel.push([r,f,rp,d.marker.storyId,d.marker.storyPath,JSON.stringify(Object.keys(d.marker.iterations||{})),JSON.stringify(Object.keys((d.revisores||{}).por_vuelta||{}))]);}catch{}}}
console.log(tot);console.log(rel.map(x=>x.join(" | ")).join("n"));'
